    },
    {
      "id": "C10",
      "status": "fail",
      "source_evidence": "The surrounding source concerns real scalar or vector states and hyperbolic equations, including nonlinear systems.",
      "translation_evidence": "The characterization ranges over every state type and every predicate without a source-specific instantiation.",
      "reasoning": "This is an unrestricted abstraction of the initial-data pattern. Its applicability to source instances does not establish that the complete translated property characterizes Riemann problems."
    },
    {
      "id": "C11",
      "status": "unclear",
      "source_evidence": "Equation (1.11) leaves the interface value unspecified. The preceding prose describes a single jump discontinuity but supplies no explicit inequality between the states.",
